using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// This succeeds (default resolver handles Person)
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"\nTryGetTypeInfo<Person> succeeded — Type: {info!.Type.Name}");
}

// Use a resolver that only knows about Person, so Widget is NOT resolvable
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // no-op modifier; resolver still only resolves what it can
        })
};

// Wrap in a custom resolver that deliberately returns null for Widget
limited.TypeInfoResolver = new SelectiveResolver(typeof(Person));

if (limited.TryGetTypeInfo<Widget>(out JsonTypeInfo<Widget>? widgetInfo))
{
    Console.WriteLine($"Unexpected: resolved Widget — {widgetInfo!.Type.Name}");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo<Widget> returned false — no exception thrown.");
}

// --- Types ---
public record Person(string Name, int Age);
public record Widget(string Id, double Price);

// A resolver that only resolves a fixed set of types
file sealed class SelectiveResolver : IJsonTypeInfoResolver
{
    private readonly HashSet<Type> _allowed;
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public SelectiveResolver(params Type[] allowed) =>
        _allowed = new HashSet<Type>(allowed);

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) =>
        _allowed.Contains(type) ? _inner.GetTypeInfo(type, options) : null;
}

